"""Per-node filter store: which compiled filter each node is enforcing."""

from __future__ import annotations

from .filter_runtime import FilterRuntime


class FilterStore:
    """One FilterRuntime per node. Missing / unloaded node -> pass-through."""

    def __init__(self) -> None:
        self._by_node: dict[str, FilterRuntime] = {}

    def get(self, node_id: str) -> FilterRuntime | None:
        return self._by_node.get(node_id)

    def runtime(self, node_id: str) -> FilterRuntime:
        """Get-or-create the runtime for a node."""
        rt = self._by_node.get(node_id)
        if rt is None:
            rt = FilterRuntime()
            self._by_node[node_id] = rt
        return rt

    def partition(self, node_id: str, frames: list[str]) -> tuple[list[str], list[str]]:
        """(kept, dropped). Pass everything through when no filter is loaded."""
        rt = self._by_node.get(node_id)
        if rt is None or not rt.loaded:
            return list(frames), []
        return rt.partition(frames)

    def version(self, node_id: str) -> str | None:
        rt = self._by_node.get(node_id)
        return rt.version if rt else None

"""The filter really compiles and really drops frames (ctypes, not mocked)."""

import pytest

from sentinel_edge.filter_runtime import CompileError, FilterRuntime, parse_hex

# Reference deauth/disassoc filter (the shape the backend agent converges to).
DEAUTH_C = """\
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

bool block_frame(const uint8_t *f, size_t n) {
    if (n < 1) return false;
    uint8_t type = (f[0] >> 2) & 0x3;
    uint8_t subtype = (f[0] >> 4) & 0xF;
    if (type != 0x0) return false;
    return subtype == 0xC || subtype == 0xA;
}
"""

ATTACK = [
    "c0003a01ffffffffffff00112233445500112233445500700700",  # deauth
    "a0003a01ffffffffffff00112233445500112233445500900800",  # disassoc
]
BENIGN = [
    "8000000000ffffffffffffaabbccddeeffaabbccddeeffc0006400",  # beacon
    "08422c00112233445566aabbccddeeff1122334455660010dead",  # data
]


def test_parse_hex():
    assert parse_hex("# comment") is None
    assert parse_hex("  ") is None
    assert parse_hex("c0_00 3a:01") == bytes([0xC0, 0x00, 0x3A, 0x01])
    assert parse_hex("zz") is None


def test_partition_drops_attack_keeps_benign():
    rt = FilterRuntime()
    rt.reload(DEAUTH_C, "v2", "deauth_flood")
    kept, dropped = rt.partition(ATTACK + BENIGN)
    assert dropped == ATTACK  # every attack frame actually dropped
    assert kept == BENIGN  # benign frames pass untouched
    assert rt.version == "v2"


def test_bad_c_raises_and_keeps_previous_filter():
    rt = FilterRuntime()
    rt.reload(DEAUTH_C, "v2")
    with pytest.raises(CompileError):
        rt.reload("this is not valid C", "v3")
    # The gateway keeps enforcing the previous good filter, never "pass all".
    assert rt.version == "v2"
    _, dropped = rt.partition(ATTACK)
    assert dropped == ATTACK


def test_unloaded_runtime_passes_everything():
    rt = FilterRuntime()
    assert rt.loaded is False
    assert rt.blocks(ATTACK[0]) is False

